with d as (select value r from jsonb_array_elements($q$[{"slug":"ayam-bakar","title":"Ayam Bakar","cuisine":"indonesian","meal_types":["dinner"],"diets":["no-dairy"],"difficulty":"medium","total_minutes":75,"recipe":{"id":"ayam-bakar","title":"Ayam Bakar","summary":"Javanese grilled chicken, simmered first in spiced coconut, then charred with kecap manis.","cuisine":"indonesian","diets":["no-dairy"],"mealTypes":["dinner"],"difficulty":"medium","prepMinutes":20,"cookMinutes":55,"servings":4,"onePot":false,"seasons":["summer"],"ingredientGroups":[{"title":"Spice paste","items":[{"item":"shallots","raw":"6 shallots, chopped","quantity":6,"ingredientId":"shallot","prep":"chopped"},{"item":"garlic","raw":"4 garlic cloves","quantity":4,"unit":"clove","ingredientId":"garlic"},{"item":"piece ginger","raw":"3cm piece ginger, chopped","quantity":3,"unit":"cm","ingredientId":"ginger","prep":"chopped"},{"item":"long red chillies","raw":"2 long red chillies, chopped","quantity":2,"ingredientId":"red-chilli","prep":"chopped"},{"item":"ground turmeric","raw":"1 tsp ground turmeric","quantity":1,"unit":"tsp","ingredientId":"ground-turmeric"},{"item":"ground coriander","raw":"2 tsp ground coriander","quantity":2,"unit":"tsp","ingredientId":"ground-coriander"},{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"}]},{"title":"Chicken","items":[{"item":"chicken marylands","raw":"4 chicken marylands (about 1.4kg)","quantity":4,"ingredientId":"chicken-pieces","note":"about 1.4kg"},{"item":"lemongrass","raw":"1 lemongrass stalk, bruised","quantity":1,"unit":"stalk","ingredientId":"lemongrass","prep":"bruised"},{"item":"coconut milk","raw":"200ml coconut milk","quantity":200,"unit":"ml","ingredientId":"coconut-milk"},{"item":"kecap manis","raw":"4 tbsp kecap manis","quantity":4,"unit":"tbsp","ingredientId":"kecap-manis"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"lime juice","raw":"1 tbsp lime juice","quantity":1,"unit":"tbsp","ingredientId":"lime"}]},{"title":"To serve","items":[{"item":"Steamed jasmine rice","raw":"Steamed jasmine rice","ingredientId":"jasmine-rice"},{"item":"Lebanese cucumber","raw":"1 Lebanese cucumber, sliced","quantity":1,"ingredientId":"cucumber","prep":"sliced"},{"item":"tomatoes","raw":"2 tomatoes, sliced","quantity":2,"ingredientId":"tomato","prep":"sliced"},{"item":"sambal oelek","raw":"2 tbsp sambal oelek","quantity":2,"unit":"tbsp","ingredientId":"sambal-oelek"}]}],"steps":[{"text":"Blend the shallots, garlic, ginger, chillies, turmeric and coriander to a paste with 2 tbsp water. Heat the oil in a wide, deep frying pan over medium heat and fry the paste for 5 minutes until fragrant."},{"text":"Cut each maryland in two at the joint. Add the chicken, lemongrass, coconut milk, 2 tbsp of the kecap manis, the salt and 200ml water. Bring to a simmer, cover and cook for 25 minutes, turning once."},{"text":"Uncover and simmer for 10 minutes more, until the sauce has reduced to a thick coating. Stir in the lime juice and remaining kecap manis."},{"text":"Heat a barbecue or chargrill pan to medium-high (or the oven grill to high). Grill the chicken for 8 to 10 minutes, turning and basting with the sauce, until sticky and charred in spots and 75°C at the bone."},{"text":"Serve with rice, cucumber, tomato and sambal, with any extra sauce spooned over."}],"notes":["Simmering first means the chicken is cooked through before it hits the grill, so the sugary glaze can char without burning while you wait.","Kecap manis contains wheat, so this isn't gluten-free.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"source":"user","provenance":"ai-draft"}},{"slug":"perkedel","title":"Perkedel","cuisine":"indonesian","meal_types":["snack","lunch"],"diets":["vegetarian","no-gluten","no-dairy"],"difficulty":"easy","total_minutes":60,"recipe":{"id":"perkedel","title":"Perkedel","summary":"Indonesian potato fritters, fragrant with fried shallots and nutmeg, dipped in egg and fried golden.","cuisine":"indonesian","diets":["vegetarian","no-gluten","no-dairy"],"mealTypes":["snack","lunch"],"difficulty":"easy","prepMinutes":25,"cookMinutes":35,"servings":4,"onePot":false,"ingredientGroups":[{"items":[{"item":"floury potatoes","raw":"800g floury potatoes, peeled and cut into chunks","quantity":800,"unit":"g","ingredientId":"potato","prep":"peeled and cut into chunks"},{"item":"fried shallots","raw":"3 tbsp fried shallots, crushed","quantity":3,"unit":"tbsp","ingredientId":"fried-shallots","prep":"crushed"},{"item":"spring onions","raw":"2 spring onions, finely sliced","quantity":2,"ingredientId":"spring-onion","prep":"finely sliced"},{"item":"chopped celery leaves","raw":"2 tbsp chopped celery leaves","quantity":2,"unit":"tbsp","ingredientId":"celery"},{"item":"ground nutmeg","raw":"1/4 tsp ground nutmeg","quantity":0.25,"unit":"tsp","ingredientId":"nutmeg"},{"item":"ground white pepper","raw":"1/4 tsp ground white pepper","quantity":0.25,"unit":"tsp","ingredientId":"white-pepper"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"eggs","raw":"2 eggs","quantity":2,"ingredientId":"egg"},{"item":"neutral oil","raw":"125ml neutral oil, for shallow-frying","quantity":125,"unit":"ml","ingredientId":"neutral-oil","prep":"for shallow-frying"}]},{"title":"To serve","items":[{"item":"sweet chilli sauce","raw":"2 tbsp sweet chilli sauce","quantity":2,"unit":"tbsp","ingredientId":"sweet-chilli-sauce"}]}],"steps":[{"text":"Boil the potatoes in salted water for 15 minutes until tender. Drain well and leave in the hot pan for 2 minutes to steam dry."},{"text":"Mash until smooth, then mix in the fried shallots, spring onion, celery leaves, nutmeg, white pepper, salt and 1 of the eggs, lightly beaten. Leave to cool for 10 minutes."},{"text":"With wet hands, shape into 12 patties about 1.5cm thick."},{"text":"Beat the other egg in a shallow bowl. Heat the oil in a large frying pan over medium heat. Dip each patty in the egg and fry in batches for 3 minutes each side, until golden. Drain on paper towel."},{"text":"Serve warm with sweet chilli sauce, or alongside soto ayam or rice."}],"notes":["Floury potatoes such as Sebago or Coliban make the lightest fritters. Waxy ones go gluey.","For the meaty version, fry 150g beef mince until cooked through and mix it into the potato."],"source":"user","provenance":"ai-draft"}},{"slug":"sayur-lodeh","title":"Sayur Lodeh","cuisine":"indonesian","meal_types":["dinner","lunch"],"diets":["vegetarian","vegan","no-gluten","no-dairy"],"difficulty":"easy","total_minutes":50,"recipe":{"id":"sayur-lodeh","title":"Sayur Lodeh","summary":"A gentle Indonesian vegetable curry in turmeric coconut broth, with tofu puffs.","cuisine":"indonesian","diets":["vegetarian","vegan","no-gluten","no-dairy"],"mealTypes":["dinner","lunch"],"difficulty":"easy","prepMinutes":25,"cookMinutes":25,"servings":4,"onePot":true,"ingredientGroups":[{"title":"Spice paste","items":[{"item":"shallots","raw":"5 shallots, chopped","quantity":5,"ingredientId":"shallot","prep":"chopped"},{"item":"garlic","raw":"3 garlic cloves","quantity":3,"unit":"clove","ingredientId":"garlic"},{"item":"long red chilli","raw":"1 long red chilli, chopped","quantity":1,"ingredientId":"red-chilli","prep":"chopped"},{"item":"macadamias","raw":"3 macadamias","quantity":3,"ingredientId":"macadamias"},{"item":"piece galangal","raw":"2cm piece galangal, chopped","quantity":2,"unit":"cm","ingredientId":"galangal","prep":"chopped"},{"item":"ground turmeric","raw":"1 tsp ground turmeric","quantity":1,"unit":"tsp","ingredientId":"ground-turmeric"},{"item":"ground coriander","raw":"1 tsp ground coriander","quantity":1,"unit":"tsp","ingredientId":"ground-coriander"},{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"}]},{"title":"Curry","items":[{"item":"lemongrass","raw":"1 lemongrass stalk, bruised","quantity":1,"unit":"stalk","ingredientId":"lemongrass","prep":"bruised"},{"item":"bay","raw":"2 bay leaves","quantity":2,"unit":"leaf","ingredientId":"bay-leaf"},{"item":"coconut milk","raw":"400ml coconut milk","quantity":400,"unit":"ml","ingredientId":"coconut-milk"},{"item":"vegetable stock","raw":"500ml vegetable stock","quantity":500,"unit":"ml","ingredientId":"vegetable-stock"},{"item":"carrot","raw":"1 carrot, sliced","quantity":1,"ingredientId":"carrot","prep":"sliced"},{"item":"Asian eggplant","raw":"1 Asian eggplant, cut into chunks","quantity":1,"ingredientId":"asian-eggplant","prep":"cut into chunks"},{"item":"green beans","raw":"150g green beans, cut into 4cm lengths","quantity":150,"unit":"g","ingredientId":"green-beans","prep":"cut into 4cm lengths"},{"item":"wombok","raw":"1/4 wombok, cut into 3cm pieces","quantity":0.25,"ingredientId":"wombok","prep":"cut into 3cm pieces"},{"item":"tofu puffs","raw":"150g tofu puffs, halved","quantity":150,"unit":"g","ingredientId":"tofu-puffs","prep":"halved"},{"item":"palm sugar","raw":"1 tbsp palm sugar, grated","quantity":1,"unit":"tbsp","ingredientId":"palm-sugar","prep":"grated"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"}]},{"title":"To serve","items":[{"item":"Steamed jasmine rice","raw":"Steamed jasmine rice","ingredientId":"jasmine-rice"},{"item":"fried shallots","raw":"2 tbsp fried shallots","quantity":2,"unit":"tbsp","ingredientId":"fried-shallots"}]}],"steps":[{"text":"Blend the shallots, garlic, chilli, macadamias, galangal, turmeric and coriander with 2 tbsp water to a paste."},{"text":"Heat the oil in a large saucepan over medium heat and fry the paste with the lemongrass and bay leaves for 5 minutes, until fragrant."},{"text":"Add the coconut milk and stock and bring to a gentle simmer. Add the carrot and eggplant and simmer for 8 minutes."},{"text":"Add the beans, wombok and tofu puffs, palm sugar and salt and simmer for 6 to 8 minutes more, until all the vegetables are tender. Don't let it boil hard or the coconut milk can split."},{"text":"Remove the lemongrass and bay leaves, taste for salt and serve in bowls with rice, scattered with fried shallots."}],"notes":["In Java it's usually seasoned with shrimp paste. Add 1/2 tsp with the spice paste if you're not keeping it vegetarian.","Indonesian salam leaves are traditional; bay leaves are the closest supermarket swap."],"source":"user","provenance":"ai-draft"}},{"slug":"sinigang","title":"Pork Sinigang","cuisine":"filipino","meal_types":["dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"easy","total_minutes":110,"recipe":{"id":"sinigang","title":"Pork Sinigang","summary":"A sour Filipino tamarind soup of tender pork ribs, radish, beans and greens.","cuisine":"filipino","diets":["no-gluten","no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":15,"cookMinutes":95,"servings":4,"onePot":true,"seasons":["autumn","winter"],"ingredientGroups":[{"items":[{"item":"pork spare ribs","raw":"1kg pork spare ribs, cut into single ribs","quantity":1,"unit":"kg","ingredientId":"pork-ribs","prep":"cut into single ribs"},{"item":"water","raw":"2 litres water","quantity":2,"unit":"l","ingredientId":"water"},{"item":"brown onion","raw":"1 brown onion, quartered","quantity":1,"ingredientId":"brown-onion","prep":"quartered"},{"item":"tomatoes","raw":"3 tomatoes, quartered","quantity":3,"ingredientId":"tomato","prep":"quartered"},{"item":"fish sauce","raw":"3 tbsp fish sauce","quantity":3,"unit":"tbsp","ingredientId":"fish-sauce"},{"item":"tamarind paste","raw":"4 tbsp tamarind paste","quantity":4,"unit":"tbsp","ingredientId":"tamarind-paste"},{"item":"daikon","raw":"300g daikon, peeled, halved and sliced 1cm thick","quantity":300,"unit":"g","ingredientId":"daikon","prep":"peeled, halved and sliced 1cm thick"},{"item":"long green chillies","raw":"2 long green chillies","quantity":2,"ingredientId":"green-chilli"},{"item":"Asian eggplant","raw":"1 Asian eggplant, sliced","quantity":1,"ingredientId":"asian-eggplant","prep":"sliced"},{"item":"green beans","raw":"150g green beans, cut into 5cm lengths","quantity":150,"unit":"g","ingredientId":"green-beans","prep":"cut into 5cm lengths"},{"item":"English spinach","raw":"1 bunch English spinach, trimmed","quantity":1,"unit":"bunch","ingredientId":"spinach","prep":"trimmed"}]},{"title":"To serve","items":[{"item":"Steamed jasmine rice","raw":"Steamed jasmine rice","ingredientId":"jasmine-rice"}]}],"steps":[{"text":"Put the pork in a large pot, cover with the water and bring to the boil. Skim off the foam for the first 5 minutes."},{"text":"Add the onion, tomatoes and 2 tbsp of the fish sauce. Simmer gently, partly covered, for 1 hour 15 minutes, until the pork is tender and pulling from the bone."},{"text":"Stir in the tamarind, then add the daikon and whole chillies and simmer for 8 minutes."},{"text":"Add the eggplant and beans and simmer for 5 minutes more, until tender."},{"text":"Taste and add more fish sauce for salt or more tamarind for sourness. It should be clearly sour. Stir in the spinach until just wilted and serve in bowls with rice."}],"notes":["Kangkong (water spinach) is the traditional green; use it if you find it at an Asian grocer.","Packet sinigang mix from Asian grocers can replace the tamarind paste. Most contain flavour enhancers and some contain wheat, so check the label.","Food safety: Cook fresh pork to at least 70°C in the thickest part."],"source":"user","provenance":"ai-draft"}},{"slug":"bistek-tagalog","title":"Bistek Tagalog","cuisine":"filipino","meal_types":["dinner"],"diets":["no-dairy"],"difficulty":"easy","total_minutes":70,"recipe":{"id":"bistek-tagalog","title":"Bistek Tagalog","summary":"Filipino beef steak braised briefly in soy and lime, under a tangle of soft onion rings.","cuisine":"filipino","diets":["no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":45,"cookMinutes":25,"servings":4,"onePot":false,"ingredientGroups":[{"items":[{"item":"beef sirloin","raw":"600g beef sirloin, thinly sliced","quantity":600,"unit":"g","ingredientId":"beef-sirloin","prep":"thinly sliced"},{"item":"soy sauce","raw":"5 tbsp soy sauce","quantity":5,"unit":"tbsp","ingredientId":"soy-sauce"},{"item":"limes","raw":"Juice of 3 limes","quantity":3,"ingredientId":"lime","prep":"juiced"},{"item":"garlic","raw":"4 garlic cloves, crushed","quantity":4,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"black pepper","raw":"1/2 tsp black pepper","quantity":0.5,"unit":"tsp","ingredientId":"black-pepper"},{"item":"neutral oil","raw":"3 tbsp neutral oil","quantity":3,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"brown onions","raw":"2 brown onions, sliced into thick rings","quantity":2,"ingredientId":"brown-onion","prep":"sliced into thick rings"},{"item":"brown sugar","raw":"1 tsp brown sugar","quantity":1,"unit":"tsp","ingredientId":"brown-sugar"},{"item":"water","raw":"125ml water","quantity":125,"unit":"ml","ingredientId":"water"}]},{"title":"To serve","items":[{"item":"Steamed jasmine rice","raw":"Steamed jasmine rice","ingredientId":"jasmine-rice"}]}],"steps":[{"text":"Mix the beef with the soy sauce, lime juice, garlic and pepper. Cover and refrigerate for 30 minutes, or up to 4 hours."},{"text":"Heat 1 tbsp oil in a large frying pan over medium-high heat and fry the onion rings for 3 minutes, until just soft but holding their shape. Lift out."},{"text":"Lift the beef from the marinade, keeping the marinade. Add the rest of the oil to the pan and sear the beef in batches for 1 minute each side until browned. Lift out."},{"text":"Pour the marinade, sugar and water into the pan and bring to the boil, scraping up the browned bits. Return the beef, lower the heat, cover and simmer for 10 minutes."},{"text":"Uncover, return the onions and simmer for 2 minutes until the sauce is slightly reduced. Serve over rice with the sauce."}],"notes":["Calamansi is the classic citrus; lime or lemon is the supermarket swap.","Soy sauce contains wheat; use tamari to make it gluten-free.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done."],"source":"user","provenance":"ai-draft"}},{"slug":"lumpia-shanghai","title":"Lumpia Shanghai","cuisine":"filipino","meal_types":["snack"],"diets":["no-dairy"],"difficulty":"medium","total_minutes":70,"recipe":{"id":"lumpia-shanghai","title":"Lumpia Shanghai","summary":"Thin, crisp Filipino pork spring rolls, the party favourite, served with sweet chilli sauce.","cuisine":"filipino","diets":["no-dairy"],"mealTypes":["snack"],"difficulty":"medium","prepMinutes":45,"cookMinutes":25,"servings":6,"onePot":false,"ingredientGroups":[{"title":"Filling","items":[{"item":"pork mince","raw":"500g pork mince","quantity":500,"unit":"g","ingredientId":"pork-mince"},{"item":"carrot","raw":"1 carrot, finely grated","quantity":1,"ingredientId":"carrot","prep":"finely grated"},{"item":"small brown onion","raw":"1 small brown onion, very finely chopped","quantity":1,"ingredientId":"brown-onion","prep":"very finely chopped"},{"item":"garlic","raw":"3 garlic cloves, finely chopped","quantity":3,"unit":"clove","ingredientId":"garlic","prep":"finely chopped"},{"item":"spring onions","raw":"2 spring onions, finely sliced","quantity":2,"ingredientId":"spring-onion","prep":"finely sliced"},{"item":"egg","raw":"1 egg","quantity":1,"ingredientId":"egg"},{"item":"soy sauce","raw":"1 tbsp soy sauce","quantity":1,"unit":"tbsp","ingredientId":"soy-sauce"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"black pepper","raw":"1/2 tsp black pepper","quantity":0.5,"unit":"tsp","ingredientId":"black-pepper"}]},{"title":"To wrap and fry","items":[{"item":"spring roll wrappers","raw":"25 spring roll wrappers (21cm), thawed","quantity":25,"ingredientId":"spring-roll-wrappers","prep":"thawed","note":"21cm"},{"item":"neutral oil","raw":"1.5L neutral oil, for deep-frying","quantity":1.5,"unit":"l","ingredientId":"neutral-oil","prep":"for deep-frying"}]},{"title":"To serve","items":[{"item":"sweet chilli sauce","raw":"125ml sweet chilli sauce","quantity":125,"unit":"ml","ingredientId":"sweet-chilli-sauce"}]}],"steps":[{"text":"Mix the filling ingredients well with your hands."},{"text":"Keep the wrappers under a damp tea towel. Lay one with a corner pointing towards you and spread a heaped tablespoon of filling in a thin log, about 1cm thick, across the near corner. Fold the corner over, fold in the sides and roll up tightly. Seal the far corner with a dab of water. Repeat with the rest."},{"text":"Pour the oil into a large, heavy saucepan no more than one-third full and heat to 170°C. Keep a lid nearby and never leave the pan."},{"text":"Fry the rolls in batches of 6 for 5 to 6 minutes, turning, until deep golden and the filling is cooked through (75°C in the centre). Drain on a wire rack."},{"text":"Cut in half on an angle if you like and serve hot with sweet chilli sauce."}],"notes":["Keep the filling thin, about the width of a finger, so it cooks through by the time the wrapper is crisp.","Rolled, uncooked lumpia freeze well in a single layer. Fry from frozen at 160°C for 8 to 9 minutes, checking the centre reaches 75°C.","Food safety: Cook mince, sausages, meatballs and liver right through to 75°C, with no pink in the centre."],"source":"user","provenance":"ai-draft"}},{"slug":"elote","title":"Elote","cuisine":"mexican","meal_types":["snack"],"diets":["vegetarian","no-gluten"],"difficulty":"easy","total_minutes":25,"recipe":{"id":"elote","title":"Elote","summary":"Mexican street corn: chargrilled cobs slathered in lime mayo, rolled in salty cheese and chilli.","cuisine":"mexican","diets":["vegetarian","no-gluten"],"mealTypes":["snack"],"difficulty":"easy","prepMinutes":10,"cookMinutes":15,"servings":4,"onePot":false,"seasons":["summer"],"ingredientGroups":[{"items":[{"item":"corn cobs","raw":"4 corn cobs, husks removed","quantity":4,"ingredientId":"corn","prep":"husks removed"},{"item":"neutral oil","raw":"1 tbsp neutral oil","quantity":1,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"whole-egg mayonnaise","raw":"4 tbsp whole-egg mayonnaise","quantity":4,"unit":"tbsp","ingredientId":"mayonnaise"},{"item":"lime","raw":"1 lime, zested, then cut into wedges","quantity":1,"ingredientId":"lime","prep":"zested, then cut into wedges"},{"item":"feta","raw":"60g feta, very finely crumbled (or queso fresco)","quantity":60,"unit":"g","ingredientId":"feta","prep":"very finely crumbled","note":"or queso fresco"},{"item":"chilli powder","raw":"1 tsp chilli powder","quantity":1,"unit":"tsp","ingredientId":"chilli-powder"},{"item":"coriander leaves","raw":"Small handful of coriander leaves, chopped","quantity":1,"unit":"handful","ingredientId":"coriander","prep":"chopped","note":"small handful"},{"item":"salt","raw":"Pinch of salt","quantity":1,"unit":"pinch","ingredientId":"salt"}]}],"steps":[{"text":"Heat a barbecue or chargrill pan over high heat. Brush the corn with oil and cook for 10 to 12 minutes, turning every couple of minutes, until tender and charred in patches."},{"text":"Mix the mayonnaise with the lime zest and a squeeze of lime juice."},{"text":"While the corn is hot, brush it all over with the lime mayo. Roll or sprinkle with the feta, then dust with chilli powder and scatter with coriander and a little salt."},{"text":"Serve straight away with lime wedges."}],"notes":["Cotija is the cheese used in Mexico. Dry, salty feta crumbled very finely is the closest supermarket match.","For esquites, cut the charred kernels off the cobs and toss everything together in cups."],"source":"user","provenance":"ai-draft"}},{"slug":"molletes","title":"Molletes","cuisine":"mexican","meal_types":["breakfast","lunch"],"diets":["vegetarian"],"difficulty":"easy","total_minutes":35,"recipe":{"id":"molletes","title":"Molletes","summary":"Open rolls toasted with refried beans and melted cheese, topped with fresh pico de gallo.","cuisine":"mexican","diets":["vegetarian"],"mealTypes":["breakfast","lunch"],"difficulty":"easy","prepMinutes":15,"cookMinutes":20,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Refried beans","items":[{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"brown onion","raw":"1/2 brown onion, finely chopped","quantity":0.5,"ingredientId":"brown-onion","prep":"finely chopped"},{"item":"garlic","raw":"2 garlic cloves, crushed","quantity":2,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"ground cumin","raw":"1 tsp ground cumin","quantity":1,"unit":"tsp","ingredientId":"ground-cumin"},{"item":"400g tins pinto beans","raw":"2 x 400g tins pinto beans, drained, 60ml liquid kept","quantity":2,"ingredientId":"kidney-beans","prep":"drained, 60ml liquid kept"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"}]},{"title":"Pico de gallo","items":[{"item":"tomatoes","raw":"3 tomatoes, finely diced","quantity":3,"ingredientId":"tomato","prep":"finely diced"},{"item":"white onion","raw":"1/2 white onion, finely diced","quantity":0.5,"ingredientId":"white-onion","prep":"finely diced"},{"item":"jalapeño","raw":"1 jalapeño, finely chopped","quantity":1,"ingredientId":"jalapeno","prep":"finely chopped"},{"item":"coriander","raw":"Small handful of coriander, chopped","quantity":1,"unit":"handful","ingredientId":"coriander","prep":"chopped","note":"small handful"},{"item":"lime","raw":"Juice of 1 lime","quantity":1,"ingredientId":"lime","prep":"juiced"},{"item":"salt","raw":"Pinch of salt","quantity":1,"unit":"pinch","ingredientId":"salt"}]},{"title":"Molletes","items":[{"item":"bread rolls","raw":"4 bread rolls (bolillo or crusty white), split in half","quantity":4,"ingredientId":"bread-roll","prep":"split in half","note":"bolillo or crusty white"},{"item":"butter","raw":"20g butter, softened","quantity":20,"unit":"g","ingredientId":"butter","prep":"softened"},{"item":"tasty cheese","raw":"150g tasty cheese, grated","quantity":150,"unit":"g","ingredientId":"tasty-cheese","prep":"grated"}]}],"steps":[{"text":"Heat the oil in a frying pan over medium heat and cook the onion for 5 minutes until soft. Add the garlic and cumin for 1 minute, then the beans, kept liquid and salt. Cook for 5 minutes, mashing with a potato masher, until thick and mostly smooth."},{"text":"Mix the pico de gallo ingredients and set aside."},{"text":"Heat the oven grill to high. Pull out a little of the soft crumb from each roll half, spread the cut sides thinly with butter and toast under the grill for 2 minutes until golden at the edges."},{"text":"Spread each half thickly with beans and top with cheese. Grill for 3 to 4 minutes, until the cheese is melted and bubbling."},{"text":"Spoon pico de gallo over the top and serve straight away."}],"notes":["Bolillo rolls are traditional; any crusty white roll works.","Good with a fried egg on top, or a spoonful of salsa verde."],"source":"user","provenance":"ai-draft"}},{"slug":"sopa-de-fideo","title":"Sopa de Fideo","cuisine":"mexican","meal_types":["lunch","dinner"],"diets":["no-dairy"],"difficulty":"easy","total_minutes":35,"recipe":{"id":"sopa-de-fideo","title":"Sopa de Fideo","summary":"Toasted thin noodles simmered in a tomato and chicken broth, finished with avocado and lime.","cuisine":"mexican","diets":["no-dairy"],"mealTypes":["lunch","dinner"],"difficulty":"easy","prepMinutes":10,"cookMinutes":25,"servings":4,"onePot":true,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Soup","items":[{"item":"tomatoes","raw":"3 tomatoes, roughly chopped","quantity":3,"ingredientId":"tomato","prep":"roughly chopped"},{"item":"white onion","raw":"1/2 white onion, roughly chopped","quantity":0.5,"ingredientId":"white-onion","prep":"roughly chopped"},{"item":"garlic","raw":"2 garlic cloves","quantity":2,"unit":"clove","ingredientId":"garlic"},{"item":"chicken stock","raw":"1.25L chicken stock (or vegetable stock)","quantity":1.25,"unit":"l","ingredientId":"chicken-stock","note":"or vegetable stock"},{"item":"neutral oil","raw":"3 tbsp neutral oil","quantity":3,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"spaghettini","raw":"200g spaghettini, broken into 3cm pieces","quantity":200,"unit":"g","ingredientId":"spaghetti","prep":"broken into 3cm pieces"},{"item":"dried oregano","raw":"1/2 tsp dried oregano","quantity":0.5,"unit":"tsp","ingredientId":"dried-oregano"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"}]},{"title":"To serve","items":[{"item":"avocado","raw":"1 avocado, diced","quantity":1,"ingredientId":"avocado","prep":"diced"},{"item":"coriander leaves","raw":"Small handful of coriander leaves","quantity":1,"unit":"handful","ingredientId":"coriander","note":"small handful"},{"item":"lime","raw":"1 lime, cut into wedges","quantity":1,"ingredientId":"lime","prep":"cut into wedges"},{"item":"jalapeño","raw":"1 jalapeño, sliced (optional)","quantity":1,"ingredientId":"jalapeno","prep":"sliced","optional":true}]}],"steps":[{"text":"Blend the tomatoes, onion and garlic with 250ml of the stock until smooth."},{"text":"Heat the oil in a large saucepan over medium heat. Add the broken pasta and fry, stirring constantly, for 3 to 4 minutes until deep golden brown. Watch it closely; it turns quickly."},{"text":"Pour in the tomato mixture carefully, as it will spit, and cook for 3 minutes, stirring, until it darkens slightly."},{"text":"Add the rest of the stock, the oregano and salt. Bring to the boil, then simmer for 8 to 10 minutes, until the pasta is soft. Taste for salt."},{"text":"Ladle into bowls and top with avocado, coriander, jalapeño if using and a squeeze of lime."}],"notes":["Mexican fideo noodles are sold in some supermarkets' international aisles; broken spaghettini is the same idea.","Use vegetable stock to make it vegetarian."],"source":"user","provenance":"ai-draft"}},{"slug":"birria-tacos","title":"Birria Tacos","cuisine":"mexican","meal_types":["dinner"],"diets":["no-gluten"],"difficulty":"medium","total_minutes":240,"recipe":{"id":"birria-tacos","title":"Birria Tacos","summary":"Chilli-braised beef in crisp, cheesy tortillas fried in the stew's red fat, with the broth for dipping.","cuisine":"mexican","diets":["no-gluten"],"mealTypes":["dinner"],"difficulty":"medium","prepMinutes":30,"cookMinutes":210,"servings":6,"onePot":false,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Birria","items":[{"item":"dried guajillo chillies","raw":"4 dried guajillo chillies, stems and seeds removed","quantity":4,"ingredientId":"dried-chilli","prep":"stems and seeds removed"},{"item":"dried ancho chillies","raw":"3 dried ancho chillies, stems and seeds removed","quantity":3,"ingredientId":"dried-chilli","prep":"stems and seeds removed"},{"item":"beef chuck","raw":"1.5kg beef chuck, cut into 4 large pieces","quantity":1.5,"unit":"kg","ingredientId":"beef-chuck","prep":"cut into 4 large pieces"},{"item":"salt","raw":"2 tsp salt","quantity":2,"unit":"tsp","ingredientId":"salt"},{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"brown onion","raw":"1 brown onion, quartered","quantity":1,"ingredientId":"brown-onion","prep":"quartered"},{"item":"garlic","raw":"6 garlic cloves, peeled","quantity":6,"unit":"clove","ingredientId":"garlic","prep":"peeled"},{"item":"chipotles in adobo","raw":"2 chipotles in adobo","quantity":2,"ingredientId":"chipotle-in-adobo"},{"item":"crushed tomatoes","raw":"400g tin crushed tomatoes","quantity":400,"unit":"g","ingredientId":"tinned-tomatoes","note":"tin"},{"item":"apple cider vinegar","raw":"2 tbsp apple cider vinegar","quantity":2,"unit":"tbsp","ingredientId":"apple-cider-vinegar"},{"item":"ground cumin","raw":"1 tsp ground cumin","quantity":1,"unit":"tsp","ingredientId":"ground-cumin"},{"item":"dried oregano","raw":"1 tsp dried oregano","quantity":1,"unit":"tsp","ingredientId":"dried-oregano"},{"item":"ground cinnamon","raw":"1/2 tsp ground cinnamon","quantity":0.5,"unit":"tsp","ingredientId":"ground-cinnamon"},{"item":"ground cloves","raw":"1/4 tsp ground cloves","quantity":0.25,"unit":"tsp","ingredientId":"ground-cloves"},{"item":"bay","raw":"2 bay leaves","quantity":2,"unit":"leaf","ingredientId":"bay-leaf"},{"item":"beef stock","raw":"1L beef stock","quantity":1,"unit":"l","ingredientId":"beef-stock"}]},{"title":"Tacos","items":[{"item":"small corn tortillas","raw":"18 small corn tortillas","quantity":18,"ingredientId":"corn-tortilla"},{"item":"mozzarella","raw":"150g mozzarella, grated","quantity":150,"unit":"g","ingredientId":"mozzarella","prep":"grated"},{"item":"white onion","raw":"1 white onion, finely diced","quantity":1,"ingredientId":"white-onion","prep":"finely diced"},{"item":"coriander","raw":"Handful of coriander, chopped","quantity":1,"unit":"handful","ingredientId":"coriander","prep":"chopped"},{"item":"limes","raw":"2 limes, cut into wedges","quantity":2,"ingredientId":"lime","prep":"cut into wedges"}]}],"steps":[{"text":"Toast the dried chillies in a dry frying pan over medium heat for 30 seconds a side, until they smell fragrant but haven't blackened. Put them in a bowl, cover with boiling water and soak for 20 minutes."},{"text":"Season the beef with the salt. Heat the oil in a large flameproof casserole over medium-high heat and brown the beef well on all sides, in batches, about 8 minutes. Set aside."},{"text":"Heat the oven to 160°C (140°C fan-forced). Drain the chillies and blend them with the onion, garlic, chipotles, tomatoes, vinegar, cumin, oregano, cinnamon, cloves and 250ml of the stock until very smooth."},{"text":"Pour the sauce into the casserole and fry, stirring, for 5 minutes until it darkens. Add the rest of the stock, the bay leaves and the beef. Bring to a simmer, cover and braise in the oven for 3 to 3 1/2 hours, until the beef falls apart."},{"text":"Lift out the beef and shred it with two forks. Skim the red fat from the top of the broth into a small bowl. Taste the broth (the consommé) for salt and keep it hot."},{"text":"Heat a large frying pan over medium heat. Dip a tortilla in the reserved fat, lay it in the pan, scatter with a little cheese and some beef, and fold it over. Cook for 2 minutes a side, until crisp and the cheese has melted. Repeat with the rest."},{"text":"Serve the tacos with cups of hot consommé for dipping, and onion, coriander and lime on the side."}],"notes":["The birria keeps for 3 days in the fridge or 3 months in the freezer, and tastes even better the next day.","Guajillo and ancho chillies are sold at Mexican grocers and some supermarkets. Check the tortilla label if you need these gluten-free.","Food safety: Cook whole cuts of beef, lamb and pork to at least 63°C in the thickest part, then rest for 3 minutes; cook pork and any rolled or stuffed cuts until the juices run clear."],"source":"user","provenance":"ai-draft"}},{"slug":"gallo-pinto","title":"Gallo Pinto","cuisine":"latin-american","meal_types":["breakfast","lunch"],"diets":["vegetarian","no-dairy"],"difficulty":"easy","total_minutes":30,"recipe":{"id":"gallo-pinto","title":"Gallo Pinto","summary":"Costa Rica's breakfast of rice and black beans fried with onion and capsicum, with eggs and avocado.","cuisine":"latin-american","diets":["vegetarian","no-dairy"],"mealTypes":["breakfast","lunch"],"difficulty":"easy","prepMinutes":10,"cookMinutes":20,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Rice and beans","items":[{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"brown onion","raw":"1 brown onion, finely diced","quantity":1,"ingredientId":"brown-onion","prep":"finely diced"},{"item":"red capsicum","raw":"1 red capsicum, finely diced","quantity":1,"ingredientId":"capsicum","prep":"finely diced"},{"item":"garlic","raw":"2 garlic cloves, crushed","quantity":2,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"ground cumin","raw":"1/2 tsp ground cumin","quantity":0.5,"unit":"tsp","ingredientId":"ground-cumin"},{"item":"black beans","raw":"400g tin black beans, drained, with 60ml of the liquid kept","quantity":400,"unit":"g","ingredientId":"black-beans","prep":"drained, with 60ml of the liquid kept","note":"tin"},{"item":"cooked white rice","raw":"600g cooked white rice, cold from the fridge","quantity":600,"unit":"g","ingredientId":"white-rice","prep":"cold from the fridge"},{"item":"soy sauce","raw":"1 tbsp soy sauce","quantity":1,"unit":"tbsp","ingredientId":"soy-sauce"},{"item":"apple cider vinegar","raw":"1 tsp apple cider vinegar","quantity":1,"unit":"tsp","ingredientId":"apple-cider-vinegar"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"coriander","raw":"Handful of coriander, chopped","quantity":1,"unit":"handful","ingredientId":"coriander","prep":"chopped"}]},{"title":"To serve","items":[{"item":"eggs","raw":"4 eggs","quantity":4,"ingredientId":"egg"},{"item":"neutral oil","raw":"1 tbsp neutral oil","quantity":1,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"avocado","raw":"1 avocado, sliced","quantity":1,"ingredientId":"avocado","prep":"sliced"},{"item":"sour cream","raw":"100g sour cream (optional)","quantity":100,"unit":"g","ingredientId":"sour-cream","optional":true},{"item":"Hot sauce","raw":"Hot sauce, to serve","ingredientId":"hot-sauce","prep":"to serve"}]}],"steps":[{"text":"Heat the oil in a large frying pan over medium heat. Cook the onion and capsicum for 6 minutes until soft. Add the garlic and cumin and cook for 1 minute."},{"text":"Add the beans and their liquid and simmer for 2 minutes, lightly crushing a few beans with the spoon."},{"text":"Add the rice, soy sauce, vinegar and salt. Turn and fold for 5 to 6 minutes, until the rice is piping hot and coloured by the beans. Stir through the coriander."},{"text":"Meanwhile, fry the eggs in the oil in a second pan until the whites are set."},{"text":"Serve the gallo pinto with a fried egg, avocado, a spoonful of sour cream and hot sauce."}],"notes":["In Costa Rica it's seasoned with Salsa Lizano, a tangy vegetable sauce. If you find a bottle, use 2 tbsp instead of the soy sauce and vinegar.","Use rice cooked the day before and kept in the fridge. Cooked rice shouldn't sit out at room temperature.","Runny yolks aren't recommended for pregnant people, young children, older people or anyone with a weakened immune system. Fry the eggs until the yolks are firm.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"source":"user","provenance":"ai-draft"}},{"slug":"ropa-vieja","title":"Ropa Vieja","cuisine":"latin-american","meal_types":["dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"easy","total_minutes":170,"recipe":{"id":"ropa-vieja","title":"Ropa Vieja","summary":"Cuba's shredded beef, braised slowly with capsicum, tomato and cumin, finished with green olives.","cuisine":"latin-american","diets":["no-gluten","no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":20,"cookMinutes":150,"servings":6,"onePot":true,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Beef","items":[{"item":"flank steak","raw":"1.2kg flank steak (or beef skirt), cut into 4 pieces","quantity":1.2,"unit":"kg","ingredientId":"skirt-steak","prep":"cut into 4 pieces","note":"or beef skirt"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"olive oil","raw":"2 tbsp olive oil","quantity":2,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"brown onion","raw":"1 brown onion, thinly sliced","quantity":1,"ingredientId":"brown-onion","prep":"thinly sliced"},{"item":"red capsicum","raw":"1 red capsicum, thinly sliced","quantity":1,"ingredientId":"capsicum","prep":"thinly sliced"},{"item":"green capsicum","raw":"1 green capsicum, thinly sliced","quantity":1,"ingredientId":"green-capsicum","prep":"thinly sliced"},{"item":"garlic","raw":"4 garlic cloves, crushed","quantity":4,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"ground cumin","raw":"2 tsp ground cumin","quantity":2,"unit":"tsp","ingredientId":"ground-cumin"},{"item":"dried oregano","raw":"1 tsp dried oregano","quantity":1,"unit":"tsp","ingredientId":"dried-oregano"},{"item":"sweet paprika","raw":"1 tsp sweet paprika","quantity":1,"unit":"tsp","ingredientId":"paprika"},{"item":"tomato paste","raw":"2 tbsp tomato paste","quantity":2,"unit":"tbsp","ingredientId":"tomato-paste"},{"item":"dry white wine","raw":"125ml dry white wine","quantity":125,"unit":"ml","ingredientId":"white-wine"},{"item":"crushed tomatoes","raw":"400g tin crushed tomatoes","quantity":400,"unit":"g","ingredientId":"tinned-tomatoes","note":"tin"},{"item":"beef stock","raw":"375ml beef stock","quantity":375,"unit":"ml","ingredientId":"beef-stock"},{"item":"bay","raw":"2 bay leaves","quantity":2,"unit":"leaf","ingredientId":"bay-leaf"},{"item":"green olives","raw":"100g green olives, halved","quantity":100,"unit":"g","ingredientId":"green-olive","prep":"halved"}]},{"title":"To serve","items":[{"item":"Steamed white rice","raw":"Steamed white rice, to serve","ingredientId":"white-rice","prep":"to serve"},{"item":"parsley","raw":"Handful of parsley, chopped","quantity":1,"unit":"handful","ingredientId":"parsley","prep":"chopped"}]}],"steps":[{"text":"Season the beef with the salt. Heat the oil in a large heavy saucepan or casserole over medium-high heat and brown the beef well on both sides, about 8 minutes. Set aside."},{"text":"Turn the heat to medium. Add the onion and both capsicums and cook for 8 minutes until soft. Stir in the garlic, cumin, oregano and paprika for 1 minute, then the tomato paste for 1 minute more."},{"text":"Pour in the wine and let it bubble for 2 minutes, scraping up the browned bits. Add the tomatoes, stock and bay leaves, and return the beef and any juices."},{"text":"Bring to a simmer, cover and cook on low heat for 2 to 2 1/2 hours, turning the beef now and then, until it pulls apart easily."},{"text":"Lift the beef onto a board and shred it along the grain with two forks. Return it to the pot with the olives and simmer uncovered for 10 minutes, until the sauce clings. Taste for salt."},{"text":"Serve over rice, scattered with parsley."}],"notes":["Black beans and fried ripe plantain are the classic sides.","It keeps for 3 days in the fridge and freezes well.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done."],"source":"user","provenance":"ai-draft"}}]$q$::jsonb)), dn as (select r, row_number() over (partition by r->>'cuisine' order by r->>'slug') rn from d), cand as (select c.id, x.cuisine, row_number() over (partition by x.cuisine order by c.recipe_count, c.handle)-1 ix, count(*) over (partition by x.cuisine) cnt from public.cooks c join (select distinct cook_id, cuisine from public.published_recipes where status='published') x on x.cook_id=c.id where c.kind='person'), ins as (insert into public.published_recipes (cook_id,slug,title,cuisine,meal_types,diets,difficulty,total_minutes,recipe,review,status) select coalesce((select cd.id from cand cd where cd.cuisine=dn.r->>'cuisine' and cd.ix=(dn.rn-1)%cd.cnt),(select id from public.cooks where kind='official' limit 1)), dn.r->>'slug', dn.r->>'title', dn.r->>'cuisine', array(select jsonb_array_elements_text(dn.r->'meal_types')), array(select jsonb_array_elements_text(dn.r->'diets')), dn.r->>'difficulty', (dn.r->>'total_minutes')::int, jsonb_set(dn.r->'recipe','{notes}',coalesce((select jsonb_agg(n) from jsonb_array_elements(dn.r->'recipe'->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)), 'auto-checked','published' from dn where not exists (select 1 from public.published_recipes q where q.slug=dn.r->>'slug') on conflict do nothing returning id) select (select count(*) from d) expected, (select count(*) from ins) inserted;